{
  "passageId": "information-asymmetry-free-marketplace",
  "items": [
    {
      "id": "R1",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "완전한 정보를 갖는다는 이론적 가정이 현실에서는 성립하지 않는다는 모델과 현실의 괴리를 제시한다."
    },
    {
      "id": "R2",
      "type": "CAUSE",
      "otherName": "",
      "reason": "거래 상대방보다 정보가 부족한 상황이 실제로 불리한 상품 선택이라는 역선택 문제를 일으킨다."
    },
    {
      "id": "R3",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "정보 비대칭에 따른 역선택 문제에 대응하여 정부의 법적 시장 개입이 제시된다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "공급자에게 정보 제공을 강제하는 조치는 정부의 법적 시장 개입을 보여 주는 구체적 사례이다."
    },
    {
      "id": "R5",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "현실 시장의 정보 비대칭에 관한 논의를 온라인 상거래 영역으로 넓힌다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "증가하는 허위·과장 광고의 문제적 특성을 이용자의 진위·의도·편향 판별 어려움으로 구체화한다."
    },
    {
      "id": "R7",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "인공 지능 광고로 심화되는 정보 비대칭 문제에 대응하여 정부가 생성물 표시 의무를 도입하였다."
    },
    {
      "id": "R8",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "표시 의무가 이미 도입되었지만 광고성 정보 제공자까지 포괄하지 못한다는 현행 제도의 한계를 제시한다."
    },
    {
      "id": "R9",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "표시 의무가 이미 도입되었지만 정보 유통 플랫폼까지 포괄하지 못한다는 현행 제도의 한계를 제시한다."
    },
    {
      "id": "R10",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "표시 의무의 현행 범위와 확대 주장을 정부 개입을 둘러싼 엇갈린 논의라는 일반적 성격으로 정리한다."
    },
    {
      "id": "R11",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "온라인 상거래 정보에 관한 정부 개입 논의를 사회적·정치적 견해 표명의 영역으로 확대한다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "정부 개입 여부에 관한 여러 입장 중 의견 경쟁과 자율 규제를 중시하는 입장을 구체적으로 설명한다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "정부 개입 여부에 관한 여러 입장 중 의견 경쟁의 한계를 지적하며 공동 규제를 요구하는 입장을 구체화한다."
    },
    {
      "id": "R14",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "경제 영역의 완전경쟁시장 모델을 사상과 표현의 경쟁이라는 다른 영역에 가져다 쓴다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "완전경쟁시장 모델을 상정한다는 이론적 전제가 의견 경쟁으로 표현의 진위와 가치를 결정해야 한다는 주장을 뒷받침한다."
    },
    {
      "id": "R16",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "미국 연방 대법원이 사상의 자유 시장 이론을 표현 보호와 플랫폼 규제라는 구체적 사안에 적용한다."
    },
    {
      "id": "R17",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "사상의 자유 시장 이론과 우리나라 헌법 재판소가 표현의 진위와 가치를 의견 경쟁으로 해결해야 한다는 견해를 공유한다."
    },
    {
      "id": "R18",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "비판론은 정보 공급이 불균형하면 의견 경쟁 자체가 불가능하다고 지적하여 사상의 자유 시장 이론의 전제를 문제 삼는다."
    },
    {
      "id": "R19",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "허위·왜곡 정보가 시민의 판단에 쓰인다는 사실을 공동 규제를 강화해야 한다는 당위적 주장의 이유로 제시한다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "정책 담당자가 조작된 정보를 시민의 진정한 의견으로 오인할 위험이 공동 규제 강화 주장을 뒷받침한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "정보 공급 불균형으로 의견 경쟁이 불가능하다는 판단이 공동 규제를 강화해야 한다는 주장의 근거가 된다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "표현의 자유가 기본권이라는 사실에서 규제가 법적 근거를 갖추어야 한다는 당위가 도출된다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "플랫폼의 사전 자율 규제와 정부의 사후 규제는 공동 규제 강화의 구체적 실행 방식을 설명한다."
    },
    {
      "id": "R24",
      "type": "CONDITION",
      "otherName": "",
      "reason": "플랫폼의 사전 자율 규제가 미흡한 경우에 정부의 사후 규제가 이루어져야 한다는 조건을 제시한다."
    },
    {
      "id": "R25",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "비판론이 의견 경쟁의 성립 가능성과 자율 규제의 효과를 문제 삼으며 사상의 자유 시장 이론을 비판한다."
    },
    {
      "id": "R26",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "정부 개입을 둘러싼 이론적 입장 대립이 실제로 드러난 사례로 실명확인 사건을 제시한다."
    },
    {
      "id": "R27",
      "type": "INTERPRETATION",
      "otherName": "",
      "reason": "헌법 재판소 다수 의견이 실명 확인 미조치 언론사에 대한 제재 규정을 헌법적 기준에서 위헌으로 평가한다."
    },
    {
      "id": "R28",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "같은 실명확인 사건에서 정부 개입을 제한하는 다수 의견과 자율적 교정의 한계를 강조하는 소수 의견을 나란히 제시한다."
    },
    {
      "id": "R29",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "헌법 재판소 소수 의견은 허위·왜곡 정보의 자율적 교정에 한계가 있다는 점에서 비판론과 견해를 같이한다."
    },
    {
      "id": "R30",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "플랫폼과 인공 지능 활용이 일상화되었다는 사실이 정부 개입 논의를 오늘날 새겨 보아야 한다는 판단을 뒷받침한다."
    }
  ]
}

